#include "exercise.h"
#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
size_t combinations(int target, unsigned size, unsigned excluded, unsigned *out) {
    size_t n = 0;
    for (unsigned m = 0; m < 512; m++) {
        if (m & excluded)
            continue;
        int sum = 0;
        unsigned count = 0;
        for (unsigned i = 0; i < 9; i++)
            if (m & (1u << i)) {
                sum += (int)i + 1;
                count++;
            }
        if (sum == target && count == size)
            out[n++] = m;
    }
    for (size_t i = 0; i < n; i++)
        for (size_t j = i + 1; j < n; j++) {
            unsigned a = out[i], b = out[j];
            for (unsigned k = 0; k < 9; k++)
                if ((a & (1u << k)) != (b & (1u << k))) {
                    if (b & (1u << k)) {
                        out[i] = b;
                        out[j] = a;
                    }
                    break;
                }
        }
    return n;
}

