#include "exercise.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool positive(int x) { return x > 0; }
static bool bstring(const void *p) { return (*(const char *const *)p)[0] == 98; }
static void string_length(const void *p, void *out) {
    *(size_t *)out = strlen(*(const char *const *)p);
}

int main(void) {
    unsigned o[512];
    assert(combinations(10, 2, 0, o) == 4);
    assert(o[0] == ((1u << 0) | (1u << 8)));
    assert(combinations(10, 2, 1, o) == 3);
    assert(combinations(45, 9, 0, o) == 1 && o[0] == 511);
    assert(combinations(1, 2, 0, o) == 0);
    assert(combinations(0, 0, 0, o) == 1 && o[0] == 0);
    {
        unsigned actual[512];
        assert(combinations(1, 1, 0, actual) == 1);
        assert(actual[0] == 1);
    }
    {
        unsigned actual[512];
        assert(combinations(2, 1, 0, actual) == 1);
        assert(actual[0] == 2);
    }
    {
        unsigned actual[512];
        assert(combinations(3, 1, 0, actual) == 1);
        assert(actual[0] == 4);
    }
    {
        unsigned actual[512];
        assert(combinations(4, 1, 0, actual) == 1);
        assert(actual[0] == 8);
    }
    {
        unsigned actual[512];
        assert(combinations(5, 1, 0, actual) == 1);
        assert(actual[0] == 16);
    }
    {
        unsigned actual[512];
        assert(combinations(6, 1, 0, actual) == 1);
        assert(actual[0] == 32);
    }
    {
        unsigned actual[512];
        assert(combinations(7, 1, 0, actual) == 1);
        assert(actual[0] == 64);
    }
    {
        unsigned actual[512];
        assert(combinations(8, 1, 0, actual) == 1);
        assert(actual[0] == 128);
    }
    {
        unsigned actual[512];
        assert(combinations(9, 1, 0, actual) == 1);
        assert(actual[0] == 256);
    }
    {
        unsigned actual[512];
        assert(combinations(45, 9, 0, actual) == 1);
        assert(actual[0] == 511);
    }
    {
        unsigned actual[512];
        assert(combinations(7, 3, 0, actual) == 1);
        assert(actual[0] == 11);
    }
    {
        unsigned actual[512];
        assert(combinations(10, 2, 0, actual) == 4);
        assert(actual[0] == 257);
        assert(actual[1] == 130);
        assert(actual[2] == 68);
        assert(actual[3] == 40);
    }
    {
        unsigned actual[512];
        assert(combinations(10, 2, 9, actual) == 2);
        assert(actual[0] == 130);
        assert(actual[1] == 68);
    }
    return 0;
}
